import{_ as t,o as n,c as o,a2 as i}from"./chunks/framework.BXzK3EA4.js";const a="/assets/ind1.BnPirt7v.PNG",s="/assets/ind2.BLLEVr3D.PNG",r="/assets/Indstocks_1.a4e_5bVs.PNG",p="/assets/Indstocks_2.C4nSAdSh.PNG",c="/assets/Indstocks_5.zizle6nV.PNG",d="/assets/indmoney_1.Cn_YLHki.PNG",l="/assets/indmoney_2.BOMjSagi.PNG",g="/assets/indmoney_3.CCu0whts.PNG",u="/assets/indmoney_4.DQGkU9gA.PNG",h="/assets/indmoney_5.DfotyOKh.PNG",T=JSON.parse('{"title":"IndMoney (INDstocks)","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/indmoney.md","filePath":"connect-brokers/brokers/indmoney.md"}'),f={name:"connect-brokers/brokers/indmoney.md"};function m(_,e,b,y,k,I){return n(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="indmoney-indstocks" tabindex="-1">IndMoney (INDstocks) <a class="header-anchor" href="#indmoney-indstocks" aria-label="Permalink to &quot;IndMoney (INDstocks)&quot;">​</a></h1><p>IndMoney (INDstocks) is a modern trading infrastructure platform offering APIs that allow traders and developers to build, automate, and execute trading strategies.<br> Using IndMoney APIs, users can connect their IndMoney trading account with tools like <strong>Tradeboard</strong> and create their own fully self-hosted, secure algo-trading setup.</p><h3 id="steps-for-integration" tabindex="-1">Steps for Integration <a class="header-anchor" href="#steps-for-integration" aria-label="Permalink to &quot;Steps for Integration&quot;">​</a></h3><p>IndMoney uses a simple <strong>Bearer Token</strong> authentication model.</p><p>To generate a token:</p><p>Visit <a href="https://www.indstocks.com/app/api-trading" target="_blank" rel="noreferrer"><strong>https://www.indstocks.com/app/api-trading</strong></a></p><figure><img src="'+a+'" alt=""><figcaption></figcaption></figure><ol><li>Enter your registered mobile number and login with the help of OTP</li></ol><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><figure><img src="'+r+'" alt=""><figcaption></figcaption></figure><ol start="2"><li>Open the <strong>Algo Trading</strong> above the chart view</li></ol><figure><img src="'+p+'" alt=""><figcaption></figcaption></figure><ol start="3"><li>Configure Static IP</li></ol><figure><img src="'+c+'" alt=""><figcaption></figcaption></figure><ol start="4"><li>Setting up TOTP</li></ol><p>TOTP setup is a <strong>one-time</strong> step done on the INDstocks website. You need your phone with an authenticator app (Google Authenticator, Microsoft Authenticator, Authy, 2FAS or Ente Auth).</p><p>Step 1: Open the Access Tokens page</p><p>Find the <strong>Setup TOTP</strong> card at the bottom of the page and click <strong>Setup Now</strong>.</p><figure><img src="'+d+'" alt=""><figcaption></figcaption></figure><p>Step 2: Start the setup</p><p>A panel opens explaining the three steps. Click <strong>Setup TOTP</strong> at the bottom.</p><figure><img src="'+l+'" alt=""><figcaption></figcaption></figure><p>Step 3: Scan the QR code</p><p>Scan the QR code with your authenticator app, or copy the setup code beneath it and enter it manually.</p><figure><img src="'+g+'" alt=""><figcaption></figcaption></figure><p><strong>Save the setup key somewhere safe before continuing.</strong> It is shown only once and cannot be recovered. If you lose it you must disable TOTP and enrol again.</p><p>Click <strong>Continue</strong></p><p>Step 4: Confirm with a code</p><p>Enter the current 6-digit code from your authenticator app and click <strong>Enable Login</strong></p><p>You have <strong>5 minutes</strong> to complete this step. If it expires, start again from Step 1.</p><figure><img src="'+u+'" alt=""><figcaption></figcaption></figure><p>Step 5: Copy your Client ID</p><p>TOTP is now enabled. Copy the <strong>Client ID</strong> shown. This is what Tradeboard needs.</p><figure><img src="'+h+`" alt=""><figcaption></figcaption></figure><p>This generated clientId will be used in Tradeboard API Key for all authenticated API requests.</p><h3 id="environment-configuration" tabindex="-1">Environment Configuration <a class="header-anchor" href="#environment-configuration" aria-label="Permalink to &quot;Environment Configuration&quot;">​</a></h3><p>The generated client ID is used as the API Key and keep as blank for API SECRET. Below is a sample configuration for the <code>.env</code> file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Indmoney Broker Configuration</span></span>
<span class="line"><span>BROKER_API_KEY = &#39;generated_client_id_after_TOTP_setup&#39; </span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;&#39; #Keep it blank intentionally</span></span>
<span class="line"><span>REDIRECT_URL = &#39;http://127.0.0.1:5000/indmoney/callback&#39;</span></span></code></pre></div><p>Integrating Tradeboard with Indmoney&#39;s API opens up possibilities for automated trading strategies, providing a powerful tool for traders and developers to exploit market opportunities efficiently. It&#39;s essential to follow best practices for API integration, including handling rate limits, managing API keys securely, and ensuring robust error handling and logging mechanisms are in place.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/indmoney/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,42)])])}const S=t(f,[["render",m]]);export{T as __pageData,S as default};
